const Redis = require('/usr/lib/node_modules/n8n/node_modules/ioredis');
const redis = new Redis({ host: '127.0.0.1', port: 6379 });

try {
  const keys = await redis.keys('capriccio:session:*');
  const ahora = Date.now();
  const DIEZ_MIN = 10 * 60 * 1000;
  const para_recordar = [];

  for (const key of keys) {
    const raw = await redis.get(key);
    if (!raw) continue;
    let sesion;
    try { sesion = JSON.parse(raw); } catch(e) { continue; }
    const inactivo = ahora - new Date(sesion.ultima_actividad || 0).getTime();
    if (inactivo >= DIEZ_MIN && !sesion.recordatorio_enviado && sesion.etapa !== 'inicio') {
      para_recordar.push({
        key,
        numero: sesion.numero,
        remoteJid: sesion.numero + '@s.whatsapp.net',
        nombre: sesion.pedido?.nombre_cliente || '',
        etapa: sesion.etapa,
        sesionRaw: raw
      });
    }
  }

  await redis.quit();
  if (para_recordar.length === 0) return [{ json: { sinSesiones: true } }];
  return para_recordar.map(s => ({ json: s }));
} catch(e) {
  try { await redis.quit(); } catch(_) {}
  return [{ json: { error: e.message } }];
}

