const Redis = require('/usr/lib/node_modules/n8n/node_modules/ioredis');
const redis = new Redis({ host: '127.0.0.1', port: 6379 });

try {
  const { key, sesionRaw, numero } = $input.first().json;
  const sesion = JSON.parse(sesionRaw);
  sesion.recordatorio_enviado = true;
  sesion.recordatorio_timestamp = new Date().toISOString();
  await redis.set(key, JSON.stringify(sesion), 'EX', 900);
  await redis.quit();
  return [{ json: { ok: true, numero } }];
} catch(e) {
  try { await redis.quit(); } catch(_) {}
  return [{ json: { error: e.message } }];
}
